     1	using System.Collections.Generic;
     2	using System.IO;
     3	using Microsoft.Xna.Framework.Audio;
     4	using ProjectTower;
     5	using ProjectTower.config;
     6	
     7	namespace AudioEdit.sfx;
     8	
     9	public class BankCue
    10	{
    11		public string name;
    12	
    13		public List<string> bankSnd;
    14	
    15		public int[] bankSndIdx;
    16	
    17		private bool idxSet;
    18	
    19		public int selSnd;
    20	
    21		public BankCue()
    22		{
    23			bankSnd = new List<string>();
    24		}
    25	
    26		public void Read(BinaryReader reader)
    27		{
    28			name = reader.ReadString();
    29			bankSnd = new List<string>();
    30			int num = reader.ReadInt32();
    31			for (int i = 0; i < num; i++)
    32			{
    33				bankSnd.Add(reader.ReadString());
    34			}
    35		}
    36	
    37		internal void SetIdx(SoundManager sndMgr, MgrSoundBank sndBank)
    38		{
    39			bankSndIdx = new int[bankSnd.Count];
    40			for (int i = 0; i < bankSnd.Count; i++)
    41			{
    42				bankSndIdx[i] = -1;
    43				for (int j = 0; j < sndBank.bankSound.Length; j++)
    44				{
    45					if (sndBank.bankSound[j].name == bankSnd[i])
    46					{
    47						bankSndIdx[i] = j;
    48					}
    49				}
    50			}
    51			idxSet = true;
    52		}
    53	
    54		internal void Play(SoundManager sndMgr, MgrSoundBank sndBank)
    55		{
    56			if (!idxSet)
    57			{
    58				SetIdx(sndMgr, sndBank);
    59			}
    60			selSnd = ((bankSnd.Count > 1) ? Rand.GetRandomInt(0, bankSnd.Count) : 0);
    61			if (bankSndIdx[selSnd] > -1)
    62			{
    63				sndBank.bankSound[bankSndIdx[selSnd]].Play(sndMgr);
    64			}
    65		}
    66	
    67		internal float GetVol(SoundManager sndMgr, MgrSoundBank sndBank)
    68		{
    69			if (!idxSet)
    70			{
    71				SetIdx(sndMgr, sndBank);
    72			}
    73			if (bankSndIdx[selSnd] > -1)
    74			{
    75				return sndBank.bankSound[bankSndIdx[selSnd]].volume * ((float)ConfigMgr.sfx / 10f);
    76			}
    77			return 0f;
    78		}
    79	
    80		internal float GetPitch(SoundManager sndMgr, MgrSoundBank sndBank)
    81		{
    82			if (!idxSet)
    83			{
    84				SetIdx(sndMgr, sndBank);
    85			}
    86			if (bankSndIdx[selSnd] > -1)
    87			{
    88				return sndBank.bankSound[bankSndIdx[selSnd]].pitch;
    89			}
    90			return 0f;
    91		}
    92	
    93		internal SoundEffectInstance GetInstance(SoundManager sndMgr, MgrSoundBank sndBank)
    94		{
    95			if (!idxSet)
    96			{
    97				SetIdx(sndMgr, sndBank);
    98			}
    99			selSnd = Rand.GetRandomInt(0, bankSnd.Count);
   100			if (bankSndIdx[selSnd] > -1)
   101			{
   102				return sndBank.bankSound[bankSndIdx[selSnd]].GetInstance(sndMgr);
   103			}
   104			return null;
   105		}
   106	
   107		internal void Play(SoundManager sndMgr, MgrSoundBank sndBank, float volume, float pan)
   108		{
   109			if (!idxSet)
   110			{
   111				SetIdx(sndMgr, sndBank);
   112			}
   113			selSnd = Rand.GetRandomInt(0, bankSnd.Count);
   114			if (bankSndIdx[selSnd] > -1)
   115			{
   116				sndBank.bankSound[bankSndIdx[selSnd]].Play(sndMgr, volume, pan);
   117			}
   118		}
   119	
   120		internal int GetCategory(SoundManager sndMgr, MgrSoundBank sndBank, int idx)
   121		{
   122			if (!idxSet)
   123			{
   124				SetIdx(sndMgr, sndBank);
   125			}
   126			return sndBank.bankSound[bankSndIdx[0]].category;
   127		}
   128	}
=== AudioEdit.sfx/BankSound.cs
     1	using System.Collections.Generic;
     2	using System.IO;
     3	using Microsoft.Xna.Framework.Audio;
     4	using ProjectTower.config;
     5	
     6	namespace AudioEdit.sfx;
     7	
     8	public class BankSound
     9	{
    10		public string name;
    11	
    12		public List<string> wavBank;
    13	
    14		public List<string> wav;
    15	
    16		public int[] wavBankIdx;
    17	
    18		public int[] wavIdx;
    19	
    20		public float volume;
    21	
    22		public float pitch;
    23	
    24		public int category;
    25	
    26		private bool idxSet;
    27	
    28		public BankSound()
    29		{
    30			name = "";
    31			wav = new List<string>();
    32			wavBank = new List<string>();
    33			volume = 1f;
    34			pitch = 0f;
    35		}
    36	
    37		public void SetIdx(SoundManager sndMgr)
    38		{
    39			wavBankIdx = new int[wavBank.Count];
    40			wavIdx = new int[wav.Count];
    41			idxSet = true;
    42			for (int i = 0; i < wavBankIdx.Length; i++)
    43			{
    44				wavBankIdx[i] = -1;
    45				wavIdx[i] = -1;
    46				for (int j = 0; j < sndMgr.waveBank.Length; j++)
    47				{
    48					if (sndMgr.waveBank[j].title == wavBank[i])
    49					{
    50						wavBankIdx[i] = j;
    51						break;
    52					}
    53				}
    54				if (wavBankIdx[i] == -1)
    55				{
    56					idxSet = false;
    57					break;
    58				}
    59				MgrWaveBank mgrWaveBank = sndMgr.waveBank[wavBankIdx[i]];
    60				for (int k = 0; k < mgrWaveBank.bankWave.Length; k++)
    61				{
    62					if (mgrWaveBank.bankWave[k].name == wav[i])
    63					{
    64						wavIdx[i] = k;
    65						break;
    66					}
    67				}
    68				if (wavIdx[i] == -1)
    69				{
    70					idxSet = false;
    71					break;
    72				}
    73			}
    74		}
    75	
    76		public void Play(SoundManager sndMgr)
    77		{
    78			Play(sndMgr, 1f, 0f);
    79		}
    80	
    81		public void Play(SoundManager sndMgr, float playVolume, float playPan)
    82		{
    83			if (!idxSet)
    84			{
    85				SetIdx(sndMgr);
    86			}
    87			if (wavIdx == null || wavBankIdx == null)
    88			{
    89				return;
    90			}
    91			for (int i = 0; i < wavIdx.Length; i++)
    92			{
    93				if (wavBankIdx[i] > -1 && wavIdx[i] > -1)
    94				{
    95					playVolume *= (float)ConfigMgr.sfx / 10f;
    96					sndMgr.waveBank[wavBankIdx[i]].bankWave[wavIdx[i]].Play(volume * playVolume, pitch, playPan);
    97				}
    98			}
    99		}
   100	
   101		public SoundEffectInstance GetInstance(SoundManager sndMgr)
   102		{
   103			if (!idxSet)
   104			{
   105				SetIdx(sndMgr);
   106			}
   107			if (wavIdx != null && wavBankIdx != null)
   108			{
   109				for (int i = 0; i < wavIdx.Length; i++)
   110				{
   111					if (wavBankIdx[i] > -1 && wavIdx[i] > -1)
   112					{
   113						SoundEffectInstance instance = sndMgr.waveBank[wavBankIdx[i]].bankWave[wavIdx[i]].GetInstance();
   114						if (instance == null)
   115						{
   116							return null;
   117						}
   118						instance.Volume = volume;
   119						return instance;
   120					}
   121				}
   122			}
   123			return null;
   124		}
   125	
   126		public void Read(BinaryReader reader)
   127		{
   128			name = reader.ReadString();
   129			int num = reader.ReadInt32();
   130			wav = new List<string>();
   131			wavBank = new List<string>();
   132			for (int i = 0; i < num; i++)
   133			{
   134				wav.Add(reader.ReadString());
   135				wavBank.Add(reader.ReadString());
   136			}
   137			volume = reader.ReadSingle();
   138			pitch = reader.ReadSingle();
   139			category = reader.ReadInt32();
   140		}
   141	}
