     1	using System.IO;
     2	using Microsoft.Xna.Framework.Audio;
     3	
     4	namespace AudioEdit.sfx;
     5	
     6	public class MgrSoundBank
     7	{
     8		public string title;
     9	
    10		public BankSound[] bankSound;
    11	
    12		public BankCue[] bankCue;
    13	
    14		public SoundManager sndMgr;
    15	
    16		public MgrSoundBank(SoundManager sndMgr)
    17		{
    18			this.sndMgr = sndMgr;
    19			title = "";
    20		}
    21	
    22		public void Read(BinaryReader reader)
    23		{
    24			title = reader.ReadString();
    25			int num = reader.ReadInt32();
    26			this.bankSound = new BankSound[num];
    27			for (int i = 0; i < num; i++)
    28			{
    29				BankSound bankSound = new BankSound();
    30				bankSound.Read(reader);
    31				this.bankSound[i] = bankSound;
    32			}
    33			num = reader.ReadInt32();
    34			this.bankCue = new BankCue[num];
    35			for (int j = 0; j < num; j++)
