384				DrawRect(GetFlipAdjustedRect(new Rectangle(x, y, width, height), flip), 0.5f * alpha);
385				DrawRect(GetFlipAdjustedRect(new Rectangle(x, y, width - (int)reduct, height), flip), alpha, 0, 1f);
386			}
387			else
388			{
389				DrawRect(GetFlipAdjustedRect(new Rectangle(x, y, width, height), flip), 0.9f * alpha);
390			}
391			if (goalPoint > point)
392			{
393				int num = (int)goalPoint;
394				int num2 = x + (int)point - 4;
395				if (num2 < x)
396				{
397					num += num2 - x;
398					num2 = x;
399				}
400				DrawBar(GetFlipAdjustedRect(new Rectangle(num2, y, num - (int)point, height), flip), new Color(0.8f, 0.8f, 0.3f, 1f * alpha));
401			}
402			DrawBar(GetFlipAdjustedRect(new Rectangle(x, y, (int)point, height), flip), new Color(r, g, b, a * alpha));
403			if (showIncreasing && goalPoint < point)
404			{
405				int num3 = (int)goalPoint;
