412			DrawArrow(GetFlipAdjustedVec(new Vector2(x, (float)y + (float)height / 2f), flip), 0, alpha * 0.5f, (float)height / 16f);
413			DrawArrow(GetFlipAdjustedVec(new Vector2((float)x + (float)width, (float)y + (float)height / 2f - 1f), flip), 1, alpha * 0.5f, (float)height / 16f);
414			SpriteTools.End();
415			SpriteTools.BeginAlpha();
416		}
