namespace ProjectTower.menu.levels;
public class Bestiary : MenuLevel
{
	private int totalPages;
	private int page;
	private const int MONSTERS_PER_PAGE = 8;
	private List<int> monstersIdx;
	public Bestiary()
	{
		title = LocStrings.GetLocString(150);
		item = new MenuItem[1]
		{
			new MenuItem(0, "")
		};
		showTitle = true;
		showTabs = true;
		bestiary = true;
	}
	public void Init(Player p)
	{
		monstersIdx = new List<int>();
		for (int i = 0; i < MonsterCatalog.catalog.Length; i++)
		{
			if (MonsterCatalog.catalog[i].bestiary)
			{
				monstersIdx.Add(i);
			}
		}
		totalPages = monstersIdx.Count / 8;
		if (monstersIdx.Count % 8 > 0)
		{
			totalPages++;
		}
		page = 0;
		PopulatePage(p);
	}
	private void PopulatePage(Player p)
	{
		int num = ((page < totalPages - 1) ? 8 : (monstersIdx.Count % 8));
		if (num == 0)
		{
			num = 8;
		}
		item = new MenuItem[num];
		for (int i = page * 8; i < page * 8 + item.Length; i++)
		{
			MonsterDef monsterDef = MonsterCatalog.catalog[monstersIdx[i]];
			if (p.playerBeasts.HasBeast(monsterDef))
			{
				item[i % 8] = new MenuItem(i, i + 1 + ". " + monsterDef.title[Game1.language]);
				continue;
			}
			item[i % 8] = new MenuItem(i, " " + (i + 1) + ". ???");
			item[i % 8].locked = true;
		}
	}
	public override void SelectedDraw(Player p, float alpha, float scale, Rectangle dRect)
	{
		base.SelectedDraw(p, alpha, scale, dRect);
	}
	public override void SelectedUpdate(Player p)
	{
		int num = page;
		if ((InputMgr.inputProfile[0].mouseEnable || InputMgr.inputProfile[0].keyMouseEnable) && p.ID == GameStateManager.mainPlayerIdx)
		{
			if (p.keyLeft)
			{
				p.keyCatLeft = true;
			}
			if (p.keyRight)
			{
				p.keyCatRight = true;
			}
		}
		if (p.keyCatRight)
		{
			page = (page + 1) % totalPages;
		}
		if (p.keyCatLeft)
		{
			page = (page + (totalPages - 1)) % totalPages;
		}
		if (num != page)
		{
			Sound.PlaySelect();
			PopulatePage(p);
			selected = 0;
		}
		base.SelectedUpdate(p);
	}
	public override void Select(Player p, int o)
	{
		((BestiaryBeast)p.menuMgr.menuLevel[25]).Init(p, monstersIdx[selected + page * 8]);
		p.menuMgr.DoLevelTrans(25);
		base.Select(p, o);
	}
	public override void Cancel(Player p, int o)
	{
		base.Cancel(p, o);
	}
}
